def largestComponentSize(nums):
    n = len(nums)
    small = [p for p in range(2, 317) if all(p % q for q in range(2, int(p ** 0.5) + 1))]
    parent = list(range(n))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    owner = {}

    def link(prime, i):
        if prime in owner:
            ra, rb = find(i), find(owner[prime])
            if ra != rb:
                parent[ra] = rb
        else:
            owner[prime] = i

    for i, x in enumerate(nums):
        for p in small:
            if p * p > x:
                break
            if x % p == 0:
                link(p, i)
                while x % p == 0:
                    x //= p
        if x > 1:
            link(x, i)
    cnt = {}
    best = 0
    for i in range(n):
        r = find(i)
        cnt[r] = cnt.get(r, 0) + 1
        if cnt[r] > best:
            best = cnt[r]
    return best
